import type { Journey, JourneyOption, JourneyScene, JourneyWorldId } from './types';
const q = (id: string): QuestionKey => id as QuestionKey;
const option = (id: string, label: string, next: string, consequence: string, extra: Partial<JourneyOption> = {}): JourneyOption => ({ id, label, next, consequence, ...extra });
const scene = (id: string, location: string, title: string, speaker: string, text: string, objective: string, options: JourneyOption[], ending?: JourneyScene['ending']): JourneyScene => ({ id, location, title, speaker, text, objective, options, ...(ending ? { ending } : {}) });
const end = (id: string, location: string, title: string, text: string, ending: NonNullable<JourneyScene['ending']>): JourneyScene => scene(id, location, title, 'BILAN DU PARCOURS', text, title, [], ending);

